document.querySelectorAll('[data-copy]').forEach(button=>button.addEventListener('click',async()=>{const text=document.getElementById(button.dataset.copy).textContent;const status=button.parentElement.querySelector('[role=status]');try{await navigator.clipboard.writeText(text);status.textContent=button.dataset.done;}catch(e){const range=document.createRange();range.selectNodeContents(document.getElementById(button.dataset.copy));const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);status.textContent='Select and copy / 선택한 텍스트를 복사하세요 / Copie el texto seleccionado';}}));